function validate(input) {
  const [{ Follow = [] }] = input;
  const pairs = new Set();
  for (const [followee, follower] of Follow) {
    if (followee === null || follower === null) return 'Every row needs a followee and a follower.';
    if (followee.toLowerCase() === follower.toLowerCase()) return `${follower} cannot follow themselves.`;
    const key = `${followee.toLowerCase()}\u0000${follower.toLowerCase()}`;
    if (pairs.has(key)) return `(${followee}, ${follower}) appears twice.`;
    pairs.add(key);
  }
  return null;
}

