function generate(rand, size) {
  let people;
  if (size === 'small') {
    const pool = ['Alice', 'Bob', 'Cena', 'Donald', 'Edward', 'Fay'];
    people = pool.slice(0, 2 + Math.floor(rand() * (pool.length - 1)));
  } else {
    const base = ['Ana', 'Ben', 'Cleo', 'Dev', 'Eli', 'Finn', 'Gia', 'Hal', 'Ivy', 'Jon'];
    people = [];
    for (let i = 0; i < 150; i++) people.push(`${base[i % base.length]}${Math.floor(i / base.length)}`);
  }
  const target = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const pairs = new Set(), Follow = [];
  let tries = 0;
  while (Follow.length < target && tries++ < target * 20) {
    const followee = people[Math.floor(rand() * people.length)];
    const follower = people[Math.floor(rand() * people.length)];
    const key = `${followee}|${follower}`;
    if (followee === follower || pairs.has(key)) continue;
    pairs.add(key);
    Follow.push([followee, follower]);
  }
  return [{ Follow }];
}
